"""
Builds benchmarks/forest.bb with blitzcc, runs it and prints the frame times and what the frames cost: a dense night forest with a winding river, 600000
grass blades, pebbles, a bridge lit by a torch, glowing insects with lights, bump-mapped ground and bark, a river picture drawn on the GPU every frame and a
fullscreen bloom (all with render targets). The result is also saved as JSON (and added to a CSV) in benchmarks/results/.

    python3 benchmarks/forest.py [--blitzcc PATH] [--trees N] [--grass N] [--pebbles N] [--insects N] [--frames N] [--seed N] [--size WxH]
                                  [--no-bloom] [--debug] [--profile] [--label NAME] [--shot FILE] [--no-save]

--trees defaults to $BENCH_TREES or 1800, --grass (blades) to $BENCH_GRASS or 600000, --pebbles to $BENCH_PEBBLES or 14000, --insects to $BENCH_INSECTS or 40,
--frames to $BENCH_FRAMES or 600. "--quick" is a small scene and 30 frames for a look whether it works. The camera walks along the path to the bridge and
back (1200 frames), so a result is the same for the same --frames and --seed. -d builds without optimization (which BLITZ_FPS profiling needs together with
--profile); the build configuration is part of the result so runs are not mixed up.

The original Blitz3D works too, so that its speed can be compared: --blitzcc C:\\Blitz3D\\bin\\blitzcc.exe (BLITZPATH is set to the folder with bin\\ in
it unless it is set). It has no -O3 and no --profile, no draw counters (they are 0), no samplers (the BlitzLLVM build filters the textures anisotropically),
and its window can be at most 2048 in each direction. The scene uses at most a few hundred sprites and a surface never holds more than 65535 vertices.

Without a display the program runs under xvfb-run, which with Mesa means llvmpipe: the times are then mostly the CPU
rasterizing and only a smoke test. The counts (draws, triangles) are exact on any GPU.
"""
import argparse
import csv
import datetime
import json
import os
import platform
import re
import shutil
import sys
import tempfile
import time
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "../tools"))
import procutil  # noqa: E402

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)


# Direct3D 7 limits the window to 2048 in each direction (measured on Areldir: 2048x2048 works, 2049x1080 and 500x3000 fail): the original Blitz3D then stops with
# "Unable to create 3D Scene".
ORIGINAL_MAX_SIZE = 2048

def copy_synced(source, target):
    """Copies a file without a UTF-8 byte order mark (the original compiler stops at it with "Expecting end-of-file", and Windows tools like to add one) and makes
    sure it is on disk and can be read again before the compiler looks for it."""
    with open(source, "rb") as f:
        data = f.read()
    if data.startswith(b"\xef\xbb\xbf"):
        data = data[3:]
    with open(target, "wb") as f:
        f.write(data)
        f.flush()
        os.fsync(f.fileno())
    for attempt in range(20):
        try:
            with open(target, "rb") as f:
                if f.read() == data:
                    return
        except OSError:
            pass
        time.sleep(0.25)
    sys.exit("Could not read back %s." % target)


def find_compiler(given):
    if given:
        return given
    for candidate in (os.path.join(ROOT, "build", "code_compiler", "blitzcc"), os.path.join(ROOT, "build", "code_compiler", "blitzcc.exe"),
                      os.path.join(ROOT, "build", "distrib", "bin", "blitzcc.exe")):
        if os.path.isfile(candidate):
            return candidate
    return shutil.which("blitzcc") or sys.exit("blitzcc not found, build it or pass --blitzcc.")


def main():
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    parser.add_argument("--blitzcc")
    parser.add_argument("--trees", type=int, default=int(os.environ.get("BENCH_TREES", 1800)))
    parser.add_argument("--grass", type=int, default=int(os.environ.get("BENCH_GRASS", 600000)))
    parser.add_argument("--pebbles", type=int, default=int(os.environ.get("BENCH_PEBBLES", 14000)))
    parser.add_argument("--insects", type=int, default=int(os.environ.get("BENCH_INSECTS", 40)))
    parser.add_argument("--frames", type=int, default=int(os.environ.get("BENCH_FRAMES", 600)))
    parser.add_argument("--seed", type=int, default=int(os.environ.get("BENCH_SEED", 1)))
    parser.add_argument("--size", default=os.environ.get("BENCH_SIZE", "640x360"))
    parser.add_argument("--quick", action="store_true", help="a small scene, 30 frames")
    parser.add_argument("--no-bloom", action="store_true", help="without the fullscreen bloom")
    parser.add_argument("--debug", action="store_true", help="build with -d (no optimization)")
    parser.add_argument("--profile", action="store_true", help="build with --profile, for BLITZ_FPS=1")
    parser.add_argument("--label", default="", help="name of this run in the result, such as the GPU")
    parser.add_argument("--shot", help="save the last frame to this file")
    parser.add_argument("--no-save", action="store_true", help="don't write benchmarks/results/")
    args = parser.parse_args()
    if args.quick:
        args.trees, args.grass, args.pebbles, args.insects, args.frames = 100, 20000, 500, 10, 30
    width, height = args.size.lower().split("x")

    compiler = find_compiler(args.blitzcc)
    # The original Blitz3D prints only a version number for -v and has no optimization level or profiling, BlitzLLVM prints
    # "Compiler version:...". The same program is built with either, so that their speeds can be compared.
    version = " ".join(procutil.run([compiler, "-v"], capture_output=True, text=True).stdout.split())
    llvm = bool(re.search(r"Compiler version:20\d\d\.", version))
    flags = ["-d"] if args.debug else (["-O3"] if llvm else [])
    if args.profile and llvm:
        flags.append("--profile")
    if not llvm and (int(width) > ORIGINAL_MAX_SIZE or int(height) > ORIGINAL_MAX_SIZE):
        sys.exit("The original Blitz3D (Direct3D 7) cannot open a window above %dx%d, it stops with \"Unable to create 3D Scene\" (asked for %sx%s); "
                 "use --size %dx%d or less with it, or BlitzLLVM for larger windows." % (ORIGINAL_MAX_SIZE, ORIGINAL_MAX_SIZE, width, height, ORIGINAL_MAX_SIZE, ORIGINAL_MAX_SIZE))
    if not llvm:
        # The original compiler reads its runtime and libraries from BLITZPATH, the folder that has bin\ in it.
        os.environ.setdefault("BLITZPATH", os.path.dirname(os.path.dirname(os.path.abspath(compiler))))
        # Without BLITZPATH the original prints an error instead of its version.
        version = " ".join(procutil.run([compiler, "-v"], capture_output=True, text=True).stdout.split())
    runner = [] if os.environ.get("DISPLAY") or os.environ.get("WAYLAND_DISPLAY") or platform.system() == "Windows" else ["xvfb-run", "-a", "-s", "-screen 0 %sx%sx24" % (width, height)]
    if runner and not shutil.which("xvfb-run"):
        sys.exit("There is no display and no xvfb-run.")

    with tempfile.TemporaryDirectory() as directory:
        program = os.path.join(directory, "forest" + (".exe" if platform.system() == "Windows" else ""))
        # Compiled from a copy with the include of this compiler next to it, whatever folder the original compiler resolves
        # includes from.
        source = os.path.join(directory, "forest.bb")
        include = os.path.join(directory, "forest_counters.bi")
        copy_synced(os.path.join(HERE, "forest.bb"), source)
        copy_synced(os.path.join(HERE, "forest_llvm.bi" if llvm else "forest_original.bi"), include)
        # A build that fails with an include error (a file that is not visible yet right after it was written) is tried again a few times.
        for attempt in range(5):
            build = procutil.run([compiler, "-q"] + flags + ["-o", program, source], cwd=directory, capture_output=True, text=True)
            if build.returncode == 0 or "include" not in (build.stdout + build.stderr).lower() or not os.path.isfile(include):
                break
            time.sleep(1 + attempt)
        if build.returncode != 0:
            sys.exit("Building the benchmark failed (exit code %d):\n%s" % (build.returncode, (build.stdout + build.stderr)[-2000:]))
        env = dict(os.environ, BENCH_TREES=str(args.trees), BENCH_GRASS=str(args.grass), BENCH_PEBBLES=str(args.pebbles), BENCH_INSECTS=str(args.insects), BENCH_FRAMES=str(args.frames), BENCH_SEED=str(args.seed), BENCH_W=width, BENCH_H=height,
                   BENCH_FRAMETIMES=os.path.join(directory, "frametimes.txt"), BENCH_RESULT=os.path.join(directory, "result.txt"))
        if args.no_bloom:
            env["BENCH_BLOOM"] = "0"
        if args.profile and llvm:
            env["BLITZ_FPS"] = "1"
        if args.shot:
            env["BENCH_SHOT"] = os.path.abspath(args.shot)
        print("Running %d trees, %d grass blades, %d pebbles, %d insects, %d frames, %sx%s%s, build %s" % (args.trees, args.grass, args.pebbles, args.insects, args.frames, width, height, ", no bloom" if args.no_bloom else "", " ".join(flags)), flush=True)
        result = procutil.run(runner + [program], env=env, capture_output=True, text=True)
        output = result.stdout + result.stderr
        # The original Blitz3D has no stdout for a program, so the result is read from a file.
        line = None
        if os.path.isfile(env["BENCH_RESULT"]):
            line = next((l for l in open(env["BENCH_RESULT"]).read().splitlines() if "RESULT " in l), None)
        if result.returncode != 0 or line is None:
            sys.exit("The benchmark failed (exit code %d):\n%s" % (result.returncode, output[-2000:]))
        values = {k: float(v) for k, v in re.findall(r"(\w+)=([-+\d.eE]+)", line.split("RESULT ", 1)[1])}
        values["bloom"] = 0 if args.no_bloom else 1
        # With --profile the runtime reports the GPU time of the passes once a second (BLITZ_FPS=1), summed over the frames of that
        # second: the first second is left out (the sprites are made and the GPU buffers filled), the others are averaged per frame.
        gpu = {}
        if args.profile and llvm:
            frames_shown = 0
            sums = {"scene": 0.0, "2d": 0.0, "copy": 0.0, "present": 0.0, "frame": 0.0}
            shown = None
            first = True
            for l in output.splitlines():
                m = re.match(r"fps: (\d+),", l)
                if m:
                    shown = int(m.group(1))
                    continue
                m = re.match(r"\s+gpu passes: scene ([\d.]+) ms, 2d ([\d.]+) ms, copy ([\d.]+) ms, present ([\d.]+) ms, frame ([\d.]+) ms", l)
                if m and shown:
                    if first:
                        first = False
                        continue
                    frames_shown += shown
                    for k, v in zip(sums, m.groups()):
                        sums[k] += float(v)
            if frames_shown:
                gpu = {"gpu_" + k + "_ms": v / frames_shown for k, v in sums.items()}
                gpu["gpu_frames"] = frames_shown
        frametimes = []
        if os.path.isfile(env["BENCH_FRAMETIMES"]):
            frametimes = [int(l) for l in open(env["BENCH_FRAMETIMES"]).read().split()]

    record = {
        "date": datetime.datetime.now(datetime.timezone.utc).isoformat(timespec="seconds"),
        "label": args.label,
        "compiler": version if llvm else "Blitz3D " + version,
        "build": " ".join(flags),
        "platform": platform.platform(),
        "display": "xvfb" if runner else "native",
        "blitz_fps_hint": "BLITZ_FPS=1 prints the runtime timers once a second" if args.profile else "",
        "result": values,
        "gpu": gpu,
    }
    print("\n  scene       %d trees, %d grass blades, %d pebbles, %d insects%s" % (values["trees"], values["tufts"], values["pebbles"], values["insects"], ", no bloom" if args.no_bloom else ""))
    print("  created in  %12.0f ms" % values["create_ms"])
    print("  ms/frame    avg %.2f  min %.2f  median %.2f  p95 %.2f  max %.2f" % (values["ms_avg"], values["ms_min"], values["ms_median"], values["ms_p95"], values["ms_max"]))
    print("  fps         %12.1f" % values["fps"])
    print("  per frame   %.0f triangles, %.0f draw calls, %.0f pipeline binds, %.0f texture binds, %.0f buffer binds"
          % (values["tris"], values["draws"], values["pipelines"], values["textures"], values["buffers"]))
    if gpu:
        print("  gpu         scene %.3f ms, 2d %.3f ms, frame %.3f ms per frame (%d frames, from BLITZ_FPS, summed GPU passes)" % (gpu["gpu_scene_ms"], gpu["gpu_2d_ms"], gpu["gpu_frame_ms"], gpu["gpu_frames"]))
    print("  build       %s (%s)" % (record["build"] or "no options", version or "unknown compiler"))

    if not args.no_save:
        out = os.path.join(HERE, "results")
        os.makedirs(out, exist_ok=True)
        stamp = datetime.datetime.now().strftime("%Y%m%d-%H%M%S")
        name = "forest-%s-%d" % (stamp, args.grass)
        with open(os.path.join(out, name + ".json"), "w") as f:
            json.dump(dict(record, frame_times_us=frametimes), f, indent=1)
        csv_path = os.path.join(out, "forest.csv")
        new = not os.path.isfile(csv_path)
        with open(csv_path, "a", newline="") as f:
            writer = csv.writer(f)
            if new:
                writer.writerow(["date", "label", "build", "display", "trees", "tufts", "pebbles", "insects", "bloom", "frames", "seed", "ms_avg", "ms_min", "ms_median", "ms_p95", "ms_max", "fps", "tris", "draws", "pipelines", "textures", "buffers", "gpu_scene_ms", "gpu_frame_ms"])
            writer.writerow([record["date"], args.label, record["build"], record["display"]] + [values[k] for k in ("trees", "tufts", "pebbles", "insects", "bloom", "frames", "seed", "ms_avg", "ms_min", "ms_median", "ms_p95", "ms_max", "fps", "tris", "draws", "pipelines", "textures", "buffers")] + [gpu.get("gpu_scene_ms", ""), gpu.get("gpu_frame_ms", "")])
        print("  saved       benchmarks/results/%s.json and forest.csv" % name)


main()
